css:
:root{color-scheme:light dark;
--paper:#FBFCFD;--panel:#EEF1F5;--ink:#17202A;--muted:#566170;--rule:#D5DBE3;
--crit:#B42318;--high:#B04A0B;--med:#856300;--low:#2C5F8A;--pass:#1F7044;--skip:#5F6875;
--sans:"Avenir Next","Avenir","Segoe UI",system-ui,-apple-system,sans-serif;
--cond:"Avenir Next Condensed","Avenir Next","Arial Narrow","Segoe UI",system-ui,sans-serif}
@media (prefers-color-scheme:dark){:root{--paper:#0E1318;--panel:#18202A;--ink:#E6EAF0;--muted:#9AA5B3;--rule:#2B3542;
--crit:#FF8B7E;--high:#FFAE6B;--med:#E6C25A;--low:#8DB9E2;--pass:#73D29C;--skip:#A3ACB8}}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 var(--sans)}
main{max-width:1080px;margin:0 auto;padding:44px 24px 80px}
a{color:inherit;text-decoration-color:var(--muted);text-underline-offset:2px}
a:hover{text-decoration-color:currentColor}
a:focus-visible,summary:focus-visible{outline:2px solid var(--ink);outline-offset:2px}
h1,h2,.id,.facts dd,.tally b,.legend b{font-family:var(--cond);font-variant-numeric:tabular-nums lining-nums}
.c-critical{--c:var(--crit)}.c-high{--c:var(--high)}.c-medium{--c:var(--med)}.c-low{--c:var(--low)}
.c-pass{--c:var(--pass)}.c-skip{--c:var(--skip)}
.mast{display:grid;grid-template-columns:1fr auto;gap:12px 40px;align-items:end;padding-bottom:20px;border-bottom:2px solid var(--ink)}
h1{font-size:48px;line-height:1;font-weight:700;letter-spacing:-.01em;margin:0}
.host{font-size:17px;color:var(--muted);margin-top:8px}
.facts{display:grid;grid-template-columns:repeat(4,auto);gap:2px 30px;margin:0}
.facts dt{font-size:12.5px;color:var(--muted)}
.facts dd{margin:0;font-size:23px;font-weight:600;white-space:nowrap}
.tape{display:flex;gap:2px;height:36px;margin:28px 0 12px}
.tape a{flex:1 1 0;min-width:0;background:var(--c)}
.tape .c-pass,.tape .c-skip{opacity:.4}
.tape a:hover{opacity:1;outline:2px solid var(--ink);outline-offset:1px}
.legend{display:flex;flex-wrap:wrap;gap:6px 24px;margin:0;padding:0;list-style:none;font-size:14px;color:var(--muted)}
.legend li::before{content:"";display:inline-block;width:10px;height:10px;margin-right:8px;background:var(--c)}
.legend b{font-size:20px;font-weight:600;color:var(--ink);margin-right:4px}
.caption{font-size:13.5px;color:var(--muted);margin:10px 0 0}
.warn{margin:24px 0 0;padding:12px 16px;border-left:4px solid var(--crit);background:var(--panel)}
.stale{margin:16px 0 0;color:var(--muted)}
h2{font-size:28px;font-weight:600;line-height:1.1;margin:52px 0 6px;display:flex;align-items:baseline;gap:12px}
h2 small{font-family:var(--sans);font-size:15px;font-weight:400;color:var(--muted)}
.finding{border-left:4px solid var(--c);padding:20px 0 20px 22px;border-bottom:1px solid var(--rule)}
.finding header{display:grid;grid-template-columns:1fr auto;gap:0 28px}
.kicker{font-size:13.5px;color:var(--muted)}
.id{font-size:16px;font-weight:600;color:var(--c);margin-right:10px}
.finding h3{grid-column:1;font-size:19px;line-height:1.3;font-weight:600;margin:3px 0 0}
.tally{grid-column:2;grid-row:1/span 2;text-align:right;white-space:nowrap}
.tally b{display:block;font-size:42px;line-height:1;font-weight:600}
.tally span{font-size:13px;color:var(--muted)}
.prose{max-width:72ch}
.prose p{margin:10px 0 0}
.note,.docs{font-size:14px;color:var(--muted)}
.docs a{margin-right:16px}
details{margin-top:14px}
summary{cursor:pointer;font-size:14px;font-weight:600;width:fit-content}
.wrap{overflow:auto;max-height:440px;margin-top:10px;border:1px solid var(--rule)}
table{width:100%;border-collapse:collapse;font-size:13.5px}
th,td{text-align:left;padding:6px 12px;vertical-align:top;border-bottom:1px solid var(--rule)}
th{position:sticky;top:0;background:var(--panel);color:var(--muted);font-size:12.5px;font-weight:600}
td:first-child{color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}
tr:last-child td{border-bottom:0}
.checks{columns:2 340px;column-gap:44px;margin:14px 0 0;padding:0;list-style:none}
.checks li{break-inside:avoid;padding:7px 0;border-bottom:1px solid var(--rule)}
.checks small{display:block;font-size:13px;color:var(--muted)}
.about{max-width:72ch;font-size:14px;color:var(--muted);padding-left:18px}
.about li{margin:5px 0}
footer{margin-top:52px;padding-top:14px;border-top:1px solid var(--rule);font-size:13px;color:var(--muted)}
code{font-size:.9em;background:var(--panel);padding:1px 5px;overflow-wrap:anywhere}
@media (max-width:720px){main{padding:28px 16px 56px}.mast{grid-template-columns:1fr}h1{font-size:38px}
.facts{grid-template-columns:repeat(2,minmax(0,1fr))}.facts dd{white-space:normal}.tape{height:28px;gap:1px}.finding{padding-left:14px}
.finding header{grid-template-columns:1fr}.tally{grid-column:1;grid-row:auto;text-align:left;margin-top:10px}
.tally b{display:inline;font-size:32px;margin-right:6px}}
@media print{:root{--paper:#fff;--panel:#f1f1f1}main{max-width:none;padding:0}.wrap{max-height:none;overflow:visible}
summary{display:none}.finding header{break-after:avoid}}
@media print{details::details-content{content-visibility:visible}}
